std::vector<InvestigationTemplate> templates_for_scenario(const std::string& scenario) {
    std::vector<InvestigationTemplate> out;
    for (const auto& item : investigation_atlas()) {
        if (core::lower(item.scenario) == core::lower(scenario)) out.push_back(item);
    }
    return out;
}

std::vector<InvestigationTemplate> templates_for_evidence(const std::string& evidence) {
    std::vector<InvestigationTemplate> out;
    for (const auto& item : investigation_atlas()) {
        if (core::lower(item.evidence) == core::lower(evidence)) out.push_back(item);
    }
    return out;
}

std::string investigation_atlas_summary() {
    std::map<std::string, std::size_t> by_scenario;
    std::map<std::string, std::size_t> by_evidence;
    for (const auto& item : investigation_atlas()) {
        by_scenario[item.scenario]++;
        by_evidence[item.evidence]++;
    }
    std::ostringstream out;
    out << "investigation_templates=" << investigation_atlas().size();
    for (const auto& kv : by_scenario) out << "\nscenario." << kv.first << "=" << kv.second;
    for (const auto& kv : by_evidence) out << "\nevidence." << kv.first << "=" << kv.second;
    return out.str();
}

